import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import {
  detectMimeType,
  imageThumbnail,
  pdfText,
  pdfThumbnail,
  sha256Hex,
} from '#src/lib/file-processing';
import sharp from 'sharp';

// Generated by test/fixtures/uploads/generate.py (pdf skill: reportlab + pypdf).
const VALID_PDF = readFileSync('test/fixtures/uploads/valid.pdf');
const PDF_RENAMED_DOCX = readFileSync('test/fixtures/uploads/pdf-renamed.docx');

function isWebp(body: Buffer): boolean {
  return (
    body.subarray(0, 4).toString('latin1') === 'RIFF' &&
    body.subarray(8, 12).toString('latin1') === 'WEBP'
  );
}

describe('file processing on real fixtures', () => {
  it('detects a PDF by its bytes, also when it is named .docx', async () => {
    expect(await detectMimeType(VALID_PDF)).toBe('application/pdf');
    expect(await detectMimeType(PDF_RENAMED_DOCX)).toBe('application/pdf');
    expect(await detectMimeType(Buffer.from('just some text'))).toBeUndefined();
  });

  it('extracts the PDF text for search', async () => {
    expect(await pdfText(VALID_PDF)).toContain('trusslattice');
  });

  it('renders page 1 of a PDF as a WebP preview', async () => {
    const thumb = await pdfThumbnail(VALID_PDF);
    expect(isWebp(thumb)).toBe(true);
    const meta = await sharp(thumb).metadata();
    expect(meta.width).toBe(720);
    expect(meta.height).toBeGreaterThan(meta.width); // A4 portrait
  });

  it('previews images and hashes bytes', async () => {
    const png = await sharp({
      create: { width: 2000, height: 1000, channels: 3, background: '#fff' },
    })
      .png()
      .toBuffer();
    const thumb = await imageThumbnail(png);
    expect(isWebp(thumb)).toBe(true);
    expect((await sharp(thumb).metadata()).width).toBe(720);
    expect(sha256Hex(Buffer.from('abc'))).toBe(
      'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad',
    );
  });

  it('throws on a damaged PDF (the worker then skips the preview)', async () => {
    await expect(pdfThumbnail(Buffer.from('%PDF-1.7 broken'))).rejects.toThrow();
  });
});
